def find_battery_route(board, start, goal):
    width = len(board[0])
    queue = [start]
    distance = {start[1] * width + start[0]: 0}
    parent = {}
    order = []
    while len(queue) > 0:
        cell = queue.pop(0)
        order.append(cell)
        if cell == goal:
            path = [cell]
            while cell != start:
                cell = parent[cell[1] * width + cell[0]]
                path.insert(0, cell)
            return [order, path]
        for delta in [[0, -1], [1, 0], [0, 1], [-1, 0]]:
            x = cell[0] + delta[0]
            y = cell[1] + delta[1]
            if x < 0 or y < 0 or x >= width or y >= len(board):
                continue
            if board[y][x] == "#":
                continue
            key = y * width + x
            if key in distance:
                continue
            distance[key] = distance[cell[1] * width + cell[0]] + 1
            parent[key] = cell
            queue.append([x, y])
    return [order, []]
